import sys

class Employee:
    def __init__(self):
        self.salary = 100
        self.hours_worked = 0

    def getInfo(self, salary, hours_worked):
        self.salary = salary
        self.hours_worked = hours_worked

    def AddSal(self):
        if self.salary < 500:
            self.salary += 100

    def AddWorkSal(self, amount):
        self.salary += amount

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    employee_id = int(data[0])
    option = int(data[1])

    emp = Employee()

    if option == 1:
        salary = int(data[2])
        hours_worked = int(data[3])
        emp.getInfo(salary, hours_worked)
        print(f"{emp.salary}$")
    elif option == 2:
        emp.AddSal()
        print(f"{emp.salary}$")
    elif option == 3:
        amount = int(data[2])
        emp.AddWorkSal(amount)
        print(f"{emp.salary}$")

if __name__ == "__main__":
    main()
